// === Tab: mySketch.js ===
/*
A sketch for the #WCCChallenge theme "child's art"

This is another test of the p5.js 2.1 beta, using
noise in p5.strands shaders. Warped radial noise...
it kinda looks like fingerprints if you don't look too
closely! The ellipse being drawn with the shader also
gets its vertices warped a bit to look less mechanical.
*/

let fingerprintShader
let remap

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL)
	noLoop()

	fingerprintShader = baseMaterialShader().modify(() => {
		const seed = uniformFloat(() => random(1000))
		let pos = sharedVec2()
		getObjectInputs((inputs) => {
			pos = inputs.position.xy
			pos += 0.1 * [noise(pos.x * 0.3, 0, seed), noise(pos.y * 0.3, 100, seed)]
			inputs.position.xy = pos
			return inputs
		})
		getFinalColor(() => {
			const warpedPos = pos + (noise([pos * 0.1, seed]) - 0.05) * 4
			const r = sqrt(pow(warpedPos.x, 2) + pow(warpedPos.y, 2))
			const elevation = noise(r * 25) + 2*noise([pos * 0.3, 2*seed])
			return mix(
				[0, 0, 0, 0],
				[0, 0, 0, 1],
				smoothstep(0, 0.1, elevation) *
					(1 - smoothstep(0.8, 0.9, elevation)) // *
					// pow(0.2 + noise([pos * 0.3, 2*seed]), 0.9)
			)
		})
	})

	remap = baseFilterShader().modify(() => {
		let dark = color('#D15')
		let mid = color('#F7B')
		let bright = color('#fff')
		getColor((inputs, canvasContent) => {
			let brightness = texture(canvasContent, inputs.texCoord).r
			brightness = smoothstep(0, 1, brightness)
			return mix(
				mix(
					dark.array(),
					mid.array(),
					clamp(brightness * 2, 0, 1)
				),
				bright.array(),
				clamp((brightness - 0.5) * 2, 0, 1)
			)
		})
	})
}

function mousePressed() {
	redraw()
}

function draw() {
	background(255)
	const numPrints = random(10, 100)
	for (let i = 0; i < numPrints; i++) {
		push()
		translate(randomGaussian(0, width/6), randomGaussian(0, height/6))
		rotate(randomGaussian(0, PI * 0.1))
		scale(random([0.6, 0.7, 0.8, 1]))
		noStroke()
		shader(fingerprintShader)
		ellipse(0, 0, 50, 75)
		pop()
	}
	filter(BLUR, 1)
	filter(remap)
}

